DROP PROCEDURE IF EXISTS shop.recent_orders_worker;
DELIMITER //
CREATE PROCEDURE shop.recent_orders_worker() SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  WHILE i < {{loops}} DO
    SELECT COUNT(*) INTO @seen FROM (SELECT id FROM shop.orders
      WHERE updated_at >= NOW() - INTERVAL 1 DAY ORDER BY updated_at DESC LIMIT 20) x;
    SET i = i + 1;
  END WHILE;
  INSERT INTO shop.drain_log () VALUES ();
END//
DELIMITER ;
